  select id into target_edition_id
  from public.event_editions
  where id = 6 or (edition_year = 2025 and name ilike '%Chicago Marathon%')
  order by (id = 6) desc limit 1;

  if target_edition_id is null then
    return;
  end if;

  -- 1. Ensure checkpoint set for 42.195 km marathon
  select id into cps_id
  from public.race_checkpoint_sets
  where event_edition_id = target_edition_id and distance_slug = 'marathon'
  limit 1;

  if cps_id is null then
    insert into public.race_checkpoint_sets (
      event_edition_id,
      distance_slug,
      distances_m
    ) values (
      target_edition_id,
      'marathon',
      array[5000, 10000, 15000, 20000, 21097.5, 25000, 30000, 35000, 40000, 42195]::numeric[]
    ) returning id into cps_id;
  end if;

